package com.warehouse.twin.controller;
import com.baomidou.mybatisplus.core.toolkit.Wrappers; import com.warehouse.twin.common.Result; import com.warehouse.twin.entity.*; import com.warehouse.twin.service.*; import org.springframework.web.bind.annotation.*; import java.time.*; import java.util.*;
@RestController @RequestMapping("/api/twin")
public class TwinController {private final SlotService slots;private final CameraService cameras;private final WarehouseEventService events;private final AlarmService alarms;public TwinController(SlotService s,CameraService c,WarehouseEventService e,AlarmService a){slots=s;cameras=c;events=e;alarms=a;}
    @GetMapping("/warehouse-state") public Result<Map<String,Object>> state(){long total=slots.count(),occupied=slots.count(Wrappers.<Slot>lambdaQuery().eq(Slot::getStatus,"OCCUPIED")),empty=slots.count(Wrappers.<Slot>lambdaQuery().eq(Slot::getStatus,"EMPTY")),online=cameras.count(Wrappers.<Camera>lambdaQuery().eq(Camera::getOnlineStatus,1));LocalDateTime today=LocalDate.now().atStartOfDay();long put=events.count(Wrappers.<WarehouseEvent>lambdaQuery().eq(WarehouseEvent::getEventType,"PUT_IN").ge(WarehouseEvent::getEventTime,today)),take=events.count(Wrappers.<WarehouseEvent>lambdaQuery().eq(WarehouseEvent::getEventType,"TAKE_OUT").ge(WarehouseEvent::getEventTime,today)),alarm=alarms.count(Wrappers.<Alarm>lambdaQuery().ne(Alarm::getStatus,"HANDLED"));return Result.ok(Map.of("totalSlots",total,"occupiedSlots",occupied,"emptySlots",empty,"todayPutIn",put,"todayTakeOut",take,"activeAlarms",alarm,"onlineCameras",online));}
    @GetMapping("/slot-state") public Result<List<Slot>> slots(){return Result.ok(slots.list());}
    @GetMapping("/events") public Result<List<WarehouseEvent>> events(){return Result.ok(events.list(Wrappers.<WarehouseEvent>lambdaQuery().orderByDesc(WarehouseEvent::getEventTime).last("limit 100")));}}
